#!/usr/bin/env bash
# Cross-language check of the certificate generated by the real page code.
# audit-browser-test.mjs must first write SEALED_DUMP_DECISION to this path.
set -euo pipefail
cd "$(dirname "$0")/.."
CARD="${1:-/tmp/sealed-room-decision.json}"
node_modules/.bin/tsx packages/harness/src/cli.ts chain gate \
  --certify-verify "$CARD" --snapshot web/snapshot.json
python3 scripts/verify.py --card "$CARD" > /tmp/sealed-room-positive-python.log
tail -n 3 /tmp/sealed-room-positive-python.log
for LABEL in fractional-run fractional-item; do
  FRACTIONAL="${CARD%.json}.${LABEL}.json"
  node_modules/.bin/tsx packages/harness/src/cli.ts chain gate \
    --certify-verify "$FRACTIONAL" --snapshot web/snapshot.json > /tmp/sealed-room-fractional-ts.log
  python3 scripts/verify.py --card "$FRACTIONAL" > /tmp/sealed-room-fractional-py.log
  echo "PASS: TypeScript + Python preserve $LABEL criteria without truncation"
done
for ATTACK in duplicate exam summary empty; do
  FORGED="${CARD%.json}.${ATTACK}.json"
  if node_modules/.bin/tsx packages/harness/src/cli.ts chain gate \
      --certify-verify "$FORGED" --snapshot web/snapshot.json > "/tmp/sealed-room-${ATTACK}-ts.log" 2>&1; then
    echo "FAIL: TypeScript accepted $ATTACK"; exit 1
  fi
  if python3 scripts/verify.py --card "$FORGED" > "/tmp/sealed-room-${ATTACK}-py.log" 2>&1; then
    echo "FAIL: Python accepted $ATTACK"; exit 1
  fi
  case "$ATTACK" in
    duplicate) EXPECT='record-set completeness' ;;
    exam) EXPECT='exam scope' ;;
    summary) EXPECT='summary' ;;
    empty) EXPECT='verdict replay' ;;
  esac
  grep -Eq "FAIL.*${EXPECT}" "/tmp/sealed-room-${ATTACK}-ts.log"
  grep -Eq "FAIL.*${EXPECT}" "/tmp/sealed-room-${ATTACK}-py.log"
  echo "PASS: TypeScript + Python reject $ATTACK at $EXPECT"
done
